const renewConnectorJobAttemptForHost = `-- name: RenewConnectorJobAttemptForHost :execrows
UPDATE connector_job_attempts attempt
SET lease_expires_at = now() + make_interval(secs => $1::integer), updated_at = now()
FROM connector_jobs job
JOIN connector_resources connector ON connector.id = job.connector_id
WHERE job.id = attempt.job_id AND job.id = $2 AND connector.host_id = $3
  AND job.status = 'running' AND job.cancel_requested_at IS NULL AND job.deadline_at > now()
  AND attempt.attempt_token = $4 AND attempt.status IN ('leased', 'running') AND attempt.lease_expires_at > now()
`

type RenewConnectorJobAttemptForHostParams struct {
	LeaseSeconds int32       `json:"lease_seconds"`
	JobID        pgtype.UUID `json:"job_id"`
	HostID       pgtype.UUID `json:"host_id"`
	AttemptToken pgtype.UUID `json:"attempt_token"`
}

func (q *Queries) RenewConnectorJobAttemptForHost(ctx context.Context, arg RenewConnectorJobAttemptForHostParams) (int64, error) {
	result, err := q.db.Exec(ctx, renewConnectorJobAttemptForHost,
		arg.LeaseSeconds,
		arg.JobID,
		arg.HostID,
		arg.AttemptToken,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

